import{_ as e,o as t,c as r,a2 as o}from"./chunks/framework.DuPBmefI.js";const i="/hk-exam-web/assets/exam-papers/tkhc-2026-page-14.png",h="/hk-exam-web/assets/exam-papers/tkhc-2026-page-15.png",s="/hk-exam-web/assets/exam-papers/tkhc-2026-page-16.png",f=JSON.parse('{"title":"大光德萃书院 · 2026年资料 · G7 · 考试","description":"","frontmatter":{"schema":"exam-report-v3","generated_from":"assets/exam-feedback","school_slug":"tai-kwong-hilary","school_zh":"大光德萃书院","school_en":"Tai Kwong Hilary College","grade":"g7","year":"2026","year_label":"2026年资料","type":"written","title":"大光德萃书院 · 2026年资料 · G7 · 考试","anonymous":true,"source_ids":["INT-TKHC-G7-2026"],"rounds":["unknown"]},"headers":[],"relativePath":"reports/tai-kwong-hilary/g7/2026-written.md","filePath":"reports/tai-kwong-hilary/g7/2026-written.md"}'),n={name:"reports/tai-kwong-hilary/g7/2026-written.md"};function l(d,a,c,p,b,u){return t(),r("div",null,[...a[0]||(a[0]=[o('<h1 id="大光德萃书院-·-2026年资料-·-g7-·-考试" tabindex="-1">大光德萃书院 · 2026年资料 · G7 · 考试 <a class="header-anchor" href="#大光德萃书院-·-2026年资料-·-g7-·-考试" aria-label="Permalink to &quot;大光德萃书院 · 2026年资料 · G7 · 考试&quot;">​</a></h1><p><a href="/hk-exam-web/schools/tai-kwong-hilary">← 返回大光德萃书院资料库</a></p><blockquote><p>以下为匿名化、校对后的反馈摘录；部分内容保留原有表达。历史反馈仅供参考，具体安排请以当次考试通知为准。</p></blockquote><h2 id="record-int-tkhc-g7-2026" tabindex="-1">资料来源：2026年大光德萃中学中一入学考试试卷.pdf <a class="header-anchor" href="#record-int-tkhc-g7-2026" aria-label="Permalink to &quot;资料来源：2026年大光德萃中学中一入学考试试卷.pdf {#record-int-tkhc-g7-2026}&quot;">​</a></h2><p><strong>资料类型：</strong> 试卷资料</p><p><strong>入学途径：</strong> 未注明</p><p><strong>课程分支：</strong> 课程分支未注明</p><h3 id="轮次未注明-·-请以当次考试通知为准" tabindex="-1">轮次未注明 · 请以当次考试通知为准 <a class="header-anchor" href="#轮次未注明-·-请以当次考试通知为准" aria-label="Permalink to &quot;轮次未注明 · 请以当次考试通知为准&quot;">​</a></h3><blockquote><p><strong>语文：</strong> 繁体中文</p><h3 id="写作-難忘的一天" tabindex="-1">写作：難忘的一天 <a class="header-anchor" href="#写作-難忘的一天" aria-label="Permalink to &quot;写作：難忘的一天&quot;">​</a></h3><p>試以《難忘的一天》為題，在單行紙上作文，寫出讓你印象深刻的一天。</p><p>文體不限，字數最少300。時限：20分鐘。</p></blockquote><blockquote><p><strong>英语：</strong> 英语</p><h3 id="日记-班上的新同学" tabindex="-1">日记：班上的新同学 <a class="header-anchor" href="#日记-班上的新同学" aria-label="Permalink to &quot;日记：班上的新同学&quot;">​</a></h3><p>Time Limit: 20 minutes.</p><p>Please read the instructions below carefully and complete the task on your single line paper.</p><p>You are writing in your diary about a new classmate in your class.</p><p>Complete the diary in about 120 words. You may use the mind-map below to help you.</p><ul><li>Who is the new classmate?</li><li>What does he/she look like?</li><li>What happened in class?</li><li>How do you feel about him/her?</li><li>另有“？”提示，可补充其他相关内容。</li></ul><p>答题页提供日期栏及“Dear Diary,”开头。</p></blockquote><blockquote><p><strong>数学：</strong> 英语</p><h3 id="作答安排" tabindex="-1">作答安排 <a class="header-anchor" href="#作答安排" aria-label="Permalink to &quot;作答安排&quot;">​</a></h3><p>Time Limit: 20 minutes.</p><p>Section A: Multiple Choice Questions (Q.1–15). Section B: Short Response Questions (Q.16–22).</p><p>Answer ALL questions on Google Form. The use of calculator is NOT allowed.</p><p>开头另有简答题：What is Mathematics? (no more than 20 words)</p><p><a href="/hk-exam-web/assets/exam-papers/tkhc-2026.pdf">查看或下载完整空白试卷（含所有图表及答题页）</a></p><h3 id="第1题" tabindex="-1">第1题 <a class="header-anchor" href="#第1题" aria-label="Permalink to &quot;第1题&quot;">​</a></h3><p>What is the least number to be added to 978632 to make it a 7-digit number?<br> 21368<br> 21468<br> 22368<br> 22468</p><h3 id="第2题" tabindex="-1">第2题 <a class="header-anchor" href="#第2题" aria-label="Permalink to &quot;第2题&quot;">​</a></h3><p>Which of the following numbers has the digit ‘8’ in its thousands place?<br> 28.015<br> 280.015<br> 2801.5<br> 28015</p><h3 id="第3题" tabindex="-1">第3题 <a class="header-anchor" href="#第3题" aria-label="Permalink to &quot;第3题&quot;">​</a></h3><p>In the number 94728942, what is the difference in value between the two &quot;9&quot;s?<br> 0<br> 899991<br> 8999910<br> 89999100</p><h3 id="第4题" tabindex="-1">第4题 <a class="header-anchor" href="#第4题" aria-label="Permalink to &quot;第4题&quot;">​</a></h3><p>Which of the following numbers has only 4 factors?<br> 10<br> 16<br> 24<br> 25</p><h3 id="第5题" tabindex="-1">第5题 <a class="header-anchor" href="#第5题" aria-label="Permalink to &quot;第5题&quot;">​</a></h3><p>Last Sunday, the students of class 7C visited the Happy Park. There were 31 students in the class. If each admission ticket costs $305, and there is a promotion for<br> “buy 10 and get 1 extra free&quot;. How much should they pay altogether for the admission tickets?<br> $ 8540<br> $ 8845<br> $ 9150<br> $ 9455</p><h3 id="第6题" tabindex="-1">第6题 <a class="header-anchor" href="#第6题" aria-label="Permalink to &quot;第6题&quot;">​</a></h3><p>The original price of a watch was $3500. Mr. Hoo bought the watch at a discounted price of $2450. At what discount in percentage was the watch sold?<br> 20%<br> 30%<br> 70%<br> 80%</p><h3 id="第7题" tabindex="-1">第7题 <a class="header-anchor" href="#第7题" aria-label="Permalink to &quot;第7题&quot;">​</a></h3><p>What kind(s) of figures can be formed by fitting six equilateral triangles of the same size together?<br> (I) parallelogram (II) trapezium (III) regular hexagon<br> I only<br> III only<br> I and II only<br> I and III only</p><h3 id="第8题" tabindex="-1">第8题 <a class="header-anchor" href="#第8题" aria-label="Permalink to &quot;第8题&quot;">​</a></h3><p>If P is divisible by 3 and Q is divisible by 7, which of the following expressions must be divisible by 21?<br> (I) P x Q (II) P + Q (III) 6 x Q<br> I and II only<br> I and III only<br> II and III only<br> I, II and III</p><h3 id="第9题" tabindex="-1">第9题 <a class="header-anchor" href="#第9题" aria-label="Permalink to &quot;第9题&quot;">​</a></h3><p>If 153 is a common multiple of 9 and #, which of the following numbers can be #?<br> 11<br> 15<br> 31<br> 51</p><h3 id="第10题" tabindex="-1">第10题 <a class="header-anchor" href="#第10题" aria-label="Permalink to &quot;第10题&quot;">​</a></h3><p>In a class, there are 40 students in total. Two students are absent today. What percentage of the class is present?<br> 8%<br> 38%<br> 95%<br> 98%</p><h3 id="第11题" tabindex="-1">第11题 <a class="header-anchor" href="#第11题" aria-label="Permalink to &quot;第11题&quot;">​</a></h3><p>The original price of a book was $19. 10% off would be given for any purchase of<br> 30 books or above. There were 28 students in class 7A. If each student bought one book, how much should class 7A pay altogether?<br> $ 47<br> $ 53.2<br> $ 478.8<br> $ 532</p><h3 id="第12题" tabindex="-1">第12题 <a class="header-anchor" href="#第12题" aria-label="Permalink to &quot;第12题&quot;">​</a></h3><p>A shopkeeper put 31.5 kg of dried pork into packets of 0.24 kg each. How many packets of dried pork did he have? How much dried pork was left?<br> 13 packets, with 0.06 kg left<br> 13 packets, with 0.6 kg left<br> 131 packets, with 0.06 kg left<br> 131 packets, with 0.6 kg left</p><h3 id="第13题" tabindex="-1">第13题 <a class="header-anchor" href="#第13题" aria-label="Permalink to &quot;第13题&quot;">​</a></h3><p>At most how many lines of symmetry are there in the following figure?<br> 0<br> 2<br> 3<br> 4</p><p><img src="'+i+'" alt="第13题：对称图形"></p><h3 id="第14题" tabindex="-1">第14题 <a class="header-anchor" href="#第14题" aria-label="Permalink to &quot;第14题&quot;">​</a></h3><p>Which of the following solids has the same shape of cut section no matter how the solid is cut once?<br> Cube<br> Cylinder<br> Cuboid<br> Sphere</p><h3 id="第15题" tabindex="-1">第15题 <a class="header-anchor" href="#第15题" aria-label="Permalink to &quot;第15题&quot;">​</a></h3><p>According to the graph below, for how long altogether was June&#39;s body temperature at 37°C or below?<br> 4 hours<br> 2.5 hours<br> 1.5 hours<br> 1 hour</p><p><img src="'+h+'" alt="第15题体温折线图及第18题方程"></p><h3 id="第16题" tabindex="-1">第16题 <a class="header-anchor" href="#第16题" aria-label="Permalink to &quot;第16题&quot;">​</a></h3><p>List all the factors of 49.</p><h3 id="第17题" tabindex="-1">第17题 <a class="header-anchor" href="#第17题" aria-label="Permalink to &quot;第17题&quot;">​</a></h3><p>Change 5.25 into an improper fraction.</p><h3 id="第18题" tabindex="-1">第18题 <a class="header-anchor" href="#第18题" aria-label="Permalink to &quot;第18题&quot;">​</a></h3><p>Solve x for the following equation:</p><p>(3 − x) ÷ 2 = x + 1</p><h3 id="第19题" tabindex="-1">第19题 <a class="header-anchor" href="#第19题" aria-label="Permalink to &quot;第19题&quot;">​</a></h3><p>Claire has a piece of cardboard of 180 cm long and 130 cm wide. To make greeting cards, she cuts out squares of side 9 cm each. How many greeting cards can she cut out from the cardboard at most?</p><h3 id="第20题" tabindex="-1">第20题 <a class="header-anchor" href="#第20题" aria-label="Permalink to &quot;第20题&quot;">​</a></h3><p>The figure shows the remaining part of a cube after a cuboid is cut out. What is the volume of this remaining part?</p><p>图中尺寸：正方体边长10 cm；切去部分宽5 cm、深6 cm、高7 cm。</p><p><img src="'+s+'" alt="第20题立体图及第21至22题看电视时长统计图"></p><h3 id="第21题" tabindex="-1">第21题 <a class="header-anchor" href="#第21题" aria-label="Permalink to &quot;第21题&quot;">​</a></h3><p>Who spent more time on watching TV on the whole?</p><p>The compound bar chart shows the time spent on watching TV by Sally and Mandy.</p><p>比较两人一周看电视的总时长。</p><h3 id="第22题" tabindex="-1">第22题 <a class="header-anchor" href="#第22题" aria-label="Permalink to &quot;第22题&quot;">​</a></h3><p>On which day did Sally and Mandy spend the same amount of time on watching<br> TV?</p></blockquote>',11)])])}const g=e(n,[["render",l]]);export{f as __pageData,g as default};
